    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryGetContextFailure(principal, resource, request, out var decision))
            return decision;

        var validatedPrincipal = principal!;
        var validatedResource = resource!;
        var validatedRequest = request!;

        if (TryGetStateFailure(validatedPrincipal, validatedResource, validatedRequest, out decision))
